package account

import "fmt"

type Account struct{ balance int }

func New(opening int) (Account, error) {
	if opening < 0 {
		return Account{}, fmt.Errorf("negative opening balance: %d", opening)
	}
	return Account{balance: opening}, nil
}

func (a *Account) Deposit(amount int) error {
	if amount <= 0 {
		return fmt.Errorf("deposit must be positive")
	}
	a.balance += amount
	return nil
}

func (a Account) Balance() int { return a.balance }
```

**account/account_test.go**

```go
package account_test

import (
	"testing"

	"example.test/bank/account"
)

func TestDeposit(t *testing.T) {
	a, err := account.New(100)
	if err != nil {
		t.Fatal(err)
	}
	if err := a.Deposit(25); err != nil {
		t.Fatal(err)
	}
	if a.Balance() != 125 {
		t.Fatalf("balance = %d", a.Balance())
	}
}
```

**Run it**

```bash
go test ./...
```

Callers can name `Account` and its methods but cannot place an arbitrary value directly into `balance`.
